import type * as React from "react";

export interface NormalizedPosition {
  /** 0–1 fraction of container width */
  x: number;
  /** 0–1 fraction of container height */
  y: number;
}

export interface RemoteCursor {
  userId: string;
  userName: string;
  position: NormalizedPosition;
}

export interface LocalUser {
  userId: string;
  userName: string;
  /** Override the auto-assigned color for this user. */
  color?: string;
}

export interface CursorsConfig {
  /** Render an overlay cursor for the local user too. Default false — OS cursor is already visible. */
  showSelf?: boolean;
  /** Seconds of inactivity before cursor fades. Default 3. */
  idleAfter?: number;
  /** Seconds before an idle cursor is removed entirely. Default 10. */
  removeAfter?: number;
  /** Minimum ms between onMove broadcasts. Default 50. */
  throttleMs?: number;
}

export interface CursorMeta {
  userId: string;
  userName: string;
  color: string;
  isIdle: boolean;
}

export interface CursorsContextValue {
  localUser: LocalUser;
  cursors: Map<string, CursorMeta>;
  config: CursorsConfig;
  onMove?: (position: NormalizedPosition) => void;
  // Refs shared between Root (update logic) and Canvas (DOM elements)
  containerRef: React.MutableRefObject<HTMLDivElement | null>;
  positionsRef: React.MutableRefObject<Map<string, NormalizedPosition>>;
  cursorElsRef: React.MutableRefObject<Map<string, HTMLDivElement>>;
  labelElsRef: React.MutableRefObject<Map<string, HTMLDivElement>>;
  scheduleOverlap: () => void;
  // Public imperative API — consumer wires these to their transport
  updateCursor: (cursor: RemoteCursor) => void;
  removeCursor: (userId: string) => void;
}

// ─── Color ────────────────────────────────────────────────────────────────────
// 12 perceptually distinct colors; deterministic from userId so colors are
// stable across reconnects and consistent for all observers.

const PALETTE = [
  "#ef4444", "#f97316", "#eab308", "#22c55e",
  "#06b6d4", "#3b82f6", "#8b5cf6", "#ec4899",
  "#14b8a6", "#f59e0b", "#84cc16", "#6366f1",
];

export function colorFromUserId(userId: string): string {
  let hash = 0;
  for (let i = 0; i < userId.length; i++) {
    hash = ((hash << 5) - hash + userId.charCodeAt(i)) | 0;
  }
  return PALETTE[Math.abs(hash) % PALETTE.length];
}

// ─── Label overlap resolver ───────────────────────────────────────────────────
// Given N cursors, computes per-label offsets (relative to cursor tip) that
// eliminate overlaps. Works in absolute container pixels.
//
// Algorithm: iterative axis-aligned separation — for each overlapping pair,
// push apart on the axis with less penetration. Run 8 iterations (fast for
// N < 30, which covers any realistic collaboration scenario).

export interface LabelLayout {
  id: string;
  cursorX: number; // cursor tip in container px
  cursorY: number;
  labelW: number;  // measured label width
  labelH: number;  // measured label height
}

const NATURAL_DX = 12;  // label offset right of cursor tip
const NATURAL_DY = 8;   // label offset below cursor tip
const PAD = 4;          // minimum gap between labels
const ITERS = 8;

/**
 * Returns per-label offsets { dx, dy } relative to each cursor's tip position.
 * Apply as: label.style.transform = `translate(${dx}px, ${dy}px)`
 */
export function resolveLabels(
  layouts: LabelLayout[],
  containerW: number,
  containerH: number,
): Map<string, { dx: number; dy: number }> {
  // Build working rects in absolute container coords
  const rects = layouts.map((l) => ({
    id: l.id,
    x: l.cursorX + NATURAL_DX,
    y: l.cursorY + NATURAL_DY,
    w: l.labelW,
    h: l.labelH,
    cx: l.cursorX,
    cy: l.cursorY,
  }));

  for (let iter = 0; iter < ITERS; iter++) {
    for (let i = 0; i < rects.length; i++) {
      for (let j = i + 1; j < rects.length; j++) {
        const a = rects[i];
        const b = rects[j];

        // AABB overlap with padding
        const overlapX =
          Math.min(a.x + a.w + PAD, b.x + b.w + PAD) - Math.max(a.x, b.x);
        const overlapY =
          Math.min(a.y + a.h + PAD, b.y + b.h + PAD) - Math.max(a.y, b.y);

        if (overlapX <= 0 || overlapY <= 0) continue;

        // Resolve on the minimum-penetration axis
        if (overlapY < overlapX) {
          const half = overlapY / 2 + 1;
          if (a.y < b.y) { a.y -= half; b.y += half; }
          else            { a.y += half; b.y -= half; }
        } else {
          const half = overlapX / 2 + 1;
          if (a.x < b.x) { a.x -= half; b.x += half; }
          else            { a.x += half; b.x -= half; }
        }
      }
    }
  }

  // Clamp to container, convert back to cursor-relative offsets
  const result = new Map<string, { dx: number; dy: number }>();
  for (const r of rects) {
    const cx = Math.max(0, Math.min(containerW - r.w, r.x));
    const cy = Math.max(0, Math.min(containerH - r.h, r.y));
    result.set(r.id, { dx: cx - r.cx, dy: cy - r.cy });
  }
  return result;
}

// ─── Throttle ─────────────────────────────────────────────────────────────────
// Leading-edge throttle — fires immediately then suppresses for `ms`.

export function throttle<T extends (...args: never[]) => void>(
  fn: T,
  ms: number,
): (...args: Parameters<T>) => void {
  let last = 0;
  return (...args) => {
    const now = performance.now();
    if (now - last >= ms) {
      last = now;
      fn(...args);
    }
  };
}

"use client";

import * as React from "react";
import type { CursorsContextValue } from "./types";

export const CursorsCtx = React.createContext<CursorsContextValue | null>(null);

export function useCursors(): CursorsContextValue {
  const ctx = React.useContext(CursorsCtx);
  if (!ctx) throw new Error("useCursors must be used inside CursorsRoot");
  return ctx;
}

"use client";

import * as React from "react";
import { CursorsCtx } from "./cursors-context";
import {
  colorFromUserId,
  resolveLabels,
  type LabelLayout,
} from "./cursor-utils";
import type {
  CursorsConfig,
  CursorsContextValue,
  CursorMeta,
  LocalUser,
  NormalizedPosition,
  RemoteCursor,
} from "./types";

export interface CursorsRootProps {
  /** The local user's identity. */
  localUser: LocalUser;
  config?: CursorsConfig;
  /**
   * Called whenever the local cursor moves inside the canvas.
   * Wire this to your transport (WebSocket, Supabase, Partykit, etc.).
   */
  onMove?: (position: NormalizedPosition) => void;
  children: React.ReactNode;
}

export function CursorsRoot({
  localUser,
  config = {},
  onMove,
  children,
}: CursorsRootProps) {
  // ── React state: only cursor identity/presence, not positions ───────────────
  const [cursors, setCursors] = React.useState<Map<string, CursorMeta>>(
    new Map(),
  );

  // ── Refs: hot-path data, never triggers re-renders ──────────────────────────
  const containerRef = React.useRef<HTMLDivElement | null>(null);
  const positionsRef = React.useRef<Map<string, NormalizedPosition>>(new Map());
  const cursorElsRef = React.useRef<Map<string, HTMLDivElement>>(new Map());
  const labelElsRef = React.useRef<Map<string, HTMLDivElement>>(new Map());
  const rafRef = React.useRef<number | null>(null);

  // Idle / remove timers per userId
  const idleTimers = React.useRef<Map<string, ReturnType<typeof setTimeout>>>(
    new Map(),
  );
  const removeTimers = React.useRef<Map<string, ReturnType<typeof setTimeout>>>(
    new Map(),
  );

  // Stable ref so idle timer callbacks can call removeCursor without stale closure
  const removeCursorRef = React.useRef<(userId: string) => void>(() => {});

  // ── Label overlap resolver (batched per RAF) ─────────────────────────────────
  const scheduleOverlap = React.useCallback(() => {
    if (rafRef.current !== null) cancelAnimationFrame(rafRef.current);
    rafRef.current = requestAnimationFrame(() => {
      rafRef.current = null;
      const container = containerRef.current;
      if (!container) return;
      const W = container.offsetWidth;
      const H = container.offsetHeight;

      const layouts: LabelLayout[] = [];
      positionsRef.current.forEach((pos, userId) => {
        const labelEl = labelElsRef.current.get(userId);
        if (!labelEl) return;
        layouts.push({
          id: userId,
          cursorX: pos.x * W,
          cursorY: pos.y * H,
          labelW: labelEl.offsetWidth || 72,
          labelH: labelEl.offsetHeight || 22,
        });
      });

      if (layouts.length === 0) return;

      const offsets = resolveLabels(layouts, W, H);
      offsets.forEach(({ dx, dy }, userId) => {
        const labelEl = labelElsRef.current.get(userId);
        if (labelEl) {
          labelEl.style.transform = `translate(${Math.round(dx)}px, ${Math.round(dy)}px)`;
        }
      });
    });
  }, []);

  // ── removeCursor ─────────────────────────────────────────────────────────────
  const removeCursor = React.useCallback((userId: string) => {
    positionsRef.current.delete(userId);

    setCursors((prev) => {
      if (!prev.has(userId)) return prev;
      const next = new Map(prev);
      next.delete(userId);
      return next;
    });

    const it = idleTimers.current.get(userId);
    if (it !== undefined) {
      clearTimeout(it);
      idleTimers.current.delete(userId);
    }
    const rt = removeTimers.current.get(userId);
    if (rt !== undefined) {
      clearTimeout(rt);
      removeTimers.current.delete(userId);
    }
  }, []);

  React.useEffect(() => {
    removeCursorRef.current = removeCursor;
  }, [removeCursor]);

  // ── updateCursor — the hot path ───────────────────────────────────────────────
  // Called by the consumer's transport wiring on every incoming cursor event.
  // Position update is direct DOM — no React re-render on every mouse move.
  const updateCursor = React.useCallback(
    (remote: RemoteCursor) => {
      const { userId, userName, position } = remote;

      // 1. Store target position
      positionsRef.current.set(userId, position);

      // 2. Direct DOM: translate the cursor wrapper
      const cursorEl = cursorElsRef.current.get(userId);
      const container = containerRef.current;
      if (cursorEl && container) {
        const x = Math.round(position.x * container.offsetWidth);
        const y = Math.round(position.y * container.offsetHeight);
        cursorEl.style.transform = `translate(${x}px, ${y}px)`;
      }

      // 3. Batch label overlap resolution
      scheduleOverlap();

      // 4. React state — only on structural changes (new cursor, un-idle)
      setCursors((prev) => {
        const existing = prev.get(userId);
        if (existing && !existing.isIdle && existing.userName === userName)
          return prev;
        const next = new Map(prev);
        next.set(userId, {
          userId,
          userName,
          color: colorFromUserId(userId),
          isIdle: false,
        });
        return next;
      });

      // 5. Reset idle / remove timers
      const existingIdle = idleTimers.current.get(userId);
      if (existingIdle !== undefined) clearTimeout(existingIdle);
      const existingRemove = removeTimers.current.get(userId);
      if (existingRemove !== undefined) clearTimeout(existingRemove);

      const idleMs = (config.idleAfter ?? 3) * 1000;
      const removeMs = (config.removeAfter ?? 10) * 1000;

      idleTimers.current.set(
        userId,
        setTimeout(() => {
          // Fade to idle
          setCursors((prev) => {
            const c = prev.get(userId);
            if (!c || c.isIdle) return prev;
            const next = new Map(prev);
            next.set(userId, { ...c, isIdle: true });
            return next;
          });
          // Schedule removal after remaining time
          removeTimers.current.set(
            userId,
            setTimeout(
              () => removeCursorRef.current(userId),
              removeMs - idleMs,
            ),
          );
        }, idleMs),
      );
    },
    [config.idleAfter, config.removeAfter, scheduleOverlap],
  );

  // ── Cleanup on unmount ────────────────────────────────────────────────────────
  React.useEffect(() => {
    return () => {
      if (rafRef.current !== null) cancelAnimationFrame(rafRef.current);
      idleTimers.current.forEach(clearTimeout);
      removeTimers.current.forEach(clearTimeout);
    };
  }, []);

  const ctx: CursorsContextValue = {
    localUser,
    cursors,
    config,
    onMove,
    containerRef,
    positionsRef,
    cursorElsRef,
    labelElsRef,
    scheduleOverlap,
    updateCursor,
    removeCursor,
  };

  return <CursorsCtx.Provider value={ctx}>{children}</CursorsCtx.Provider>;
}

CursorsRoot.displayName = "CursorsRoot";

"use client";

import * as React from "react";
import { useCursors } from "./cursors-context";
import { throttle } from "./cursor-utils";
import type { CursorMeta } from "./types";
import { cn } from "@/lib/utils";

// ─── Cursor arrow SVG ─────────────────────────────────────────────────────────
// Hotspot at (0, 0) — the tip of the arrow.

function CursorArrow({ color }: { color: string }) {
  return (
    <svg
      width="16"
      height="20"
      viewBox="0 0 16 20"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden
      style={{ pointerEvents: "none", display: "block" }}
    >
      <path
        d="M0 0 L0 16 L4.5 12.5 L7 19.5 L9.5 18.5 L7 11.5 L12.5 11.5 Z"
        fill={color}
        stroke="white"
        strokeWidth="1.5"
        strokeLinejoin="round"
        strokeLinecap="round"
      />
    </svg>
  );
}

// ─── CursorElement ────────────────────────────────────────────────────────────
// Renders a single remote cursor + label.
// Registers its DOM refs so CursorsRoot can update positions directly.
// Applies its initial position from positionsRef on mount (handles the race
// between updateCursor being called and the React render completing).

function CursorElement({ meta }: { meta: CursorMeta }) {
  const { containerRef, positionsRef, cursorElsRef, labelElsRef } =
    useCursors();
  const wrapperRef = React.useRef<HTMLDivElement>(null);
  const labelRef = React.useRef<HTMLDivElement>(null);

  React.useLayoutEffect(() => {
    const wrapper = wrapperRef.current;
    const label = labelRef.current;
    if (!wrapper || !label) return;

    // Register with Root so imperative updates can reach these elements
    cursorElsRef.current.set(meta.userId, wrapper);
    labelElsRef.current.set(meta.userId, label);

    // Apply initial position if updateCursor was called before this element mounted
    const pos = positionsRef.current.get(meta.userId);
    const container = containerRef.current;
    if (pos && container) {
      const x = Math.round(pos.x * container.offsetWidth);
      const y = Math.round(pos.y * container.offsetHeight);
      wrapper.style.transform = `translate(${x}px, ${y}px)`;
    }

    return () => {
      cursorElsRef.current.delete(meta.userId);
      labelElsRef.current.delete(meta.userId);
    };
  }, [meta.userId]); // eslint-disable-line react-hooks/exhaustive-deps

  return (
    <div
      ref={wrapperRef}
      className={cn(
        // Position at top-left; transform moves it to cursor coords
        "absolute top-0 left-0 will-change-transform pointer-events-none",
        // Fade idle cursors; re-appearing cursors fade back in
        "transition-opacity duration-500 ease-in-out",
        meta.isIdle ? "opacity-0" : "opacity-100",
      )}
      // Hidden off-screen until first position is applied
      style={{ transform: "translate(-200px, -200px)" }}
      aria-hidden
    >
      {/* Arrow at hotspot (0,0) */}
      <CursorArrow color={meta.color} />

      {/* Name label — natural offset from cursor tip.
          Transform is overridden by the overlap resolver each frame. */}
      <div
        ref={labelRef}
        className="absolute top-0 left-0 will-change-transform"
        style={{ transform: "translate(12px, 8px)" }}
      >
        <span
          className={cn(
            "block px-1.5 py-0.5 rounded text-[11px] font-medium",
            "text-white whitespace-nowrap leading-4 shadow-sm",
          )}
          style={{ backgroundColor: meta.color }}
        >
          {meta.userName}
        </span>
      </div>
    </div>
  );
}

// ─── CursorCanvas ─────────────────────────────────────────────────────────────
// The shared surface. Wrap your page content with this.
//
// Responsibilities:
//  - Tracks the local cursor via mousemove, throttles, normalizes, calls onMove
//  - Renders a pointer-events-none overlay containing all remote cursors
//  - Sets containerRef so CursorsRoot can compute normalized positions

export interface CursorCanvasProps {
  children?: React.ReactNode;
  className?: string;
}

export function CursorCanvas({ children, className }: CursorCanvasProps) {
  const { localUser, cursors, config, onMove, containerRef } = useCursors();

  // Keep a stable ref to the throttled handler so re-renders don't re-create it
  const moveHandlerRef = React.useRef<((e: MouseEvent) => void) | null>(null);

  // Rebuild the throttled handler when throttleMs or onMove changes
  React.useEffect(() => {
    const ms = config.throttleMs ?? 50;
    moveHandlerRef.current = throttle((e: MouseEvent) => {
      const container = containerRef.current;
      if (!container || !onMove) return;
      const rect = container.getBoundingClientRect();
      const x = (e.clientX - rect.left) / rect.width;
      const y = (e.clientY - rect.top) / rect.height;
      // Ignore movement outside the canvas bounds
      if (x < 0 || x > 1 || y < 0 || y > 1) return;
      onMove({ x, y });
    }, ms);
  }, [config.throttleMs, onMove]); // eslint-disable-line react-hooks/exhaustive-deps

  // Attach the mousemove listener to the container after mount
  React.useEffect(() => {
    const container = containerRef.current;
    if (!container) return;
    const handler = (e: MouseEvent) => moveHandlerRef.current?.(e);
    container.addEventListener("mousemove", handler, { passive: true });
    return () => container.removeEventListener("mousemove", handler);
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  // Filter which cursors to render
  const visibleCursors = React.useMemo<CursorMeta[]>(() => {
    const all = Array.from(cursors.values());
    return config.showSelf
      ? all
      : all.filter((c) => c.userId !== localUser.userId);
  }, [cursors, config.showSelf, localUser.userId]);

  return (
    <div ref={containerRef} className={cn("relative", className)}>
      {children}

      {/* Cursor overlay — renders above content, no pointer events */}
      <div
        className="absolute inset-0 overflow-hidden pointer-events-none"
        aria-hidden
      >
        {visibleCursors.map((meta) => (
          <CursorElement key={meta.userId} meta={meta} />
        ))}
      </div>
    </div>
  );
}

CursorCanvas.displayName = "CursorCanvas";

export { CursorsRoot } from "./cursors-root";
export { CursorCanvas } from "./cursor-canvas";
export { useCursors } from "./cursors-context";
export type {
  NormalizedPosition,
  RemoteCursor,
  LocalUser,
  CursorsConfig,
  CursorMeta,
  // CursorsRootProps,
} from "./types";
